try{const data=JSON.parse(localStorage.getItem(STORE));state=data?.version===1&&Array.isArray(data.people)&&Array.isArray(data.channels)&&Array.isArray(data.messages)&&Array.isArray(data.requests)?data:seed();lang=state.language==='en'?'en':'uk'}catch{state=seed()}
function persist(){state.language=lang;try{localStorage.setItem(STORE,JSON.stringify(state))}catch{if(!storageWarning){storageWarning=true;toast(t('noStorage'))}}}
let toastTimer;function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3900)}
function btn(label,action,cls='primary',ico='',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${esc(label)}</button>`}
const isAway=(id,date=TODAY)=>!!companyClosure(date)||state.requests.some(r=>r.person===id&&r.status==='approved'&&r.start<=date&&r.end>=date);
const upcoming=()=>state.requests.filter(r=>r.status==='approved'&&r.end>=TODAY).sort((a,b)=>a.start.localeCompare(b.start));
const pending=()=>state.requests.filter(r=>r.status==='pending'&&r.person!==actorId());
function footer(){return `<footer class="app-footer"><span>${esc(t('demoFooter'))}</span><span><button data-action="about">${esc(t('demoAbout'))}</button> &nbsp;·&nbsp; <button data-action="reset">${esc(t('reset'))}</button></span></footer>`}
function companyLogos(variant){return `<div class="company-logo-pair company-logo-pair--${variant}" role="group" aria-label="Kehoe Equipment Ltd. and Midwest Engineering (AB) Ltd."><div class="company-logo-frame company-logo-frame--kehoe"><img src="./assets/kehoe-equipment-logo.png" alt="Kehoe Equipment Ltd." width="654" height="212" decoding="async"></div><span class="company-logo-join" aria-hidden="true">+</span><div class="company-logo-frame company-logo-frame--midwest"><img src="./assets/midwest-engineering-logo.svg" alt="Midwest Engineering (AB) Ltd." width="202" height="75" decoding="async"></div></div>`}
function render(){
 document.documentElement.lang=lang;document.title=`${t(view==='timeoff'?'timeoff':view)} · KEL Connect`;
 if(view==='admin'&&!canManage())view='overview';
 const nav=[['overview','grid'],['messages','chat'],['calendar','calendar'],['timeoff','sun'],['people','people'],...(canManage()?[['admin','shield']]:[])];
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><button class="brand" data-action="nav" data-view="overview" aria-label="KEL Connect"><span class="brand-mark">K</span><span class="brand-text">KEL <span>Connect</span><span style="display:block;font:8px 'DM Sans',sans-serif;letter-spacing:1.4px;color:#7c998b;margin-top:4px">${esc(t('connected').toUpperCase())}</span></span></button><div class="workspace-label joint-workspace">${companyLogos('sidebar')}<small>${esc(t('internal'))}</small></div><div class="nav-label">${esc(t('workspace'))}</div><nav class="nav-items">${nav.map(([v,i])=>`<button class="nav-btn ${view===v?'active':''}" data-action="nav" data-view="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${esc(t(v))}</span>${v==='timeoff'&&pending().length?`<span class="badge">${pending().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><div class="note-heading">${icon('leaf')}${esc(t('demoTitle'))}</div><p>${esc(t('demoNote'))}</p></div><div class="profile">${av(person(actorId()),'online')}<div><b>${esc(person(actorId()).name)}</b><small>${esc(t(roleKey(person(actorId()).role)))}</small></div>${icon('down')}</div></div></aside><div class="mobile-overlay" data-action="close-menu"></div><main class="app-main"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="${esc(t('menu'))}">${icon('menu')}</button><span>Workspace</span><span>${icon('right')}</span><strong>${esc(t(view))}</strong></div><div class="header-right">${personaControl()}<span class="header-date">${esc(fmt(TODAY,{weekday:'short',day:'numeric',month:'short',year:'numeric'}))}</span><button class="demo-pill" data-action="about"><span class="dot"></span>${esc(t('demo'))}</button><button class="language-toggle" data-action="language" aria-label="${lang==='uk'?'Switch to English':'Перейти на українську'}">${lang==='uk'?'EN':'UA'}</button>${av(person(actorId()),'sm')}</div></header><div class="page ${view==='messages'?'messages-page':''}">${view==='overview'?renderOverview():view==='messages'?renderMessages():view==='calendar'?renderCalendar():view==='timeoff'?renderTimeoff():view==='admin'?renderAdmin():renderPeople()}${footer()}</div></main></div>`;
 bindSearchInputs();if(view==='messages'){const panel=$('#chat-messages');if(panel)panel.scrollTop=panel.scrollHeight}
}
function pageHeading(eye,title,sub,button=''){return `<div class="page-heading"><div><p class="eyebrow">${esc(eye)}</p><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p></div>${button}</div>`}
function renderOverview(){
const next=upcoming()[0],available=state.people.filter(p=>p.active!==false&&!isAway(p.id)).length;
const recent=state.channels.filter(c=>c.kind==='group').slice(0,3);
const week=startWeek(TODAY);
return `${pageHeading(t('goodMorning'),t('todayOverview'),t('overviewSub'),btn(t('request'),'request','primary','plus'))}<div class="overview-stats"><div class="stat"><div><div class="stat-label">${esc(t('activePeople'))}</div><div class="stat-value">${available}<span style="font-size:14px;color:#a7b098;font-weight:400"> / ${state.people.filter(p=>p.active!==false).length}</span></div><div class="stat-detail">${esc(t('available'))}</div></div><span class="stat-icon">${icon('people')}</span></div><div class="stat"><div><div class="stat-label">${esc(t('pendingRequests'))}</div><div class="stat-value">${pending().length.toString().padStart(2,'0')}</div><div class="stat-detail">${esc(t('needReview'))}</div></div><span class="stat-icon">${icon('clock')}</span></div><div class="stat"><div><div class="stat-label">${esc(t('nextAway'))}</div><div class="stat-value" style="font-size:23px">${next?esc(fmt(next.start,{day:'numeric',month:'short'})):'—'}</div><div class="stat-detail">${next?esc(person(next.person).name):esc(t('noUpcoming'))}</div></div><span class="stat-icon">${icon('calendar')}</span></div></div><div class="overview-grid"><div><div class="welcome-card card joint-welcome"><div><p class="eyebrow">${esc(t('welcomeEye'))}</p><h2>${esc(t('welcomeTitle'))}</h2><p>${esc(t('welcomeBody'))}</p><button class="text-button" data-action="nav" data-view="messages" style="margin-top:15px;padding-left:0;font-size:10px">${esc(t('allChats'))}${icon('arrow')}</button></div>${companyLogos('welcome')}</div><section class="card"><div class="card-header"><h2>${esc(t('recentChats'))}</h2><button class="text-button" data-action="nav" data-view="messages">${esc(t('allChats'))}${icon('right')}</button></div>${recent.map(c=>{const ms=state.messages.filter(m=>m.channel===c.id);const last=ms.at(-1);return `<button class="recent-row" data-action="chat" data-id="${c.id}"><span class="channel-avatar">#</span><span class="recent-body"><span class="recent-top"><b>${esc(channelName(c))}</b><time>${last?timeFmt(last.at):''}</time></span><p>${last?`${esc(person(last.author).name.split(' ')[0])}: ${esc(last.text.replace(/\n/g,' '))}`:esc(t('emptyChat'))}</p></span></button>`}).join('')}<div class="section-footer">${icon('shield')}${esc(t('localOnly'))} · ${esc(t('allFictional'))}</div></section></div><div class="overview-right"><section class="card"><div class="card-header"><h2>${esc(t('upcoming'))}</h2><button class="text-button" data-action="nav" data-view="calendar">${icon('arrow')}</button></div><div class="agenda-list">${agendaRows(upcoming().slice(0,3))}</div><div class="section-footer">${icon('calendar')}${esc(t('approvedOnly'))}</div></section><section class="card" style="margin-top:22px" id="week-card"><div class="card-header"><h2>${esc(t('thisWeek'))}</h2><span style="font-size:9px;color:#a0ac91">${esc(fmt(TODAY,{month:'long',year:'numeric'}))}</span></div><div class="week-preview">${Array.from({length:7},(_,i)=>{const d=addDays(week,i),n=state.requests.filter(r=>r.status==='approved'&&r.start<=d&&r.end>=d).length;return `<div class="week-day ${d===TODAY?'today':''}">${esc(fmt(d,{weekday:'short'}))}<b>${toDate(d).getDate()}</b>${n?Array.from({length:Math.min(n,3)},()=>'<i class="week-marker"></i>').join(''):'<i class="week-marker muted-marker"></i>'}</div>`}).join('')}</div></section><div class="availability-banner"><span class="status-orb">${icon('check')}</span><div><strong>${esc(t('allAvailable'))}</strong><p>${esc(t('teamCalendarHint'))}</p></div><button class="icon-btn" data-action="nav" data-view="calendar" aria-label="${esc(t('viewCalendar'))}">${icon('right')}</button></div></div></div>`;
}
function agendaRows(requests){return requests.length?requests.map(r=>`<div class="agenda-row"><div class="date-square"><span>${esc(fmt(r.start,{month:'short'}))}</span>${toDate(r.start).getDate()}</div>${av(person(r.person),'sm')}<div><b>${esc(person(r.person).name)}</b><p>${esc(range(r.start,r.end))} · ${esc(t('away'))}</p></div></div>`).join(''):`<div class="inline-empty">${esc(t('noUpcoming'))}</div>`}
function timeFmt(at){return new Date(at).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit',timeZone:'America/Edmonton'})}
function renderMessages(){
let c=visibleChannels().find(c=>c.id===activeChat)||visibleChannels()[0];activeChat=c.id;
const filtered=visibleChannels().filter(c=>channelName(c).toLowerCase().includes(chatFilter.toLowerCase()));
const ms=state.messages.filter(m=>m.channel===c.id&&(!messageSearch||m.text.toLowerCase().includes(messageSearch.toLowerCase())));
return `${pageHeading('KEL CONNECT',t('messages'),t('messagesSub'),btn(t('newChat'),'new-group','primary','plus'))}<div class="messages-layout"><aside class="conversation-list"><div class="input-search">${icon('search')}<input id="chat-search" type="search" placeholder="${esc(t('searchChats'))}" aria-label="${esc(t('searchChats'))}" value="${esc(chatFilter)}"></div><div id="conversations">${conversationItems(filtered,c)}</div><div class="mini-info">${icon('lock')}<br>${esc(t('demoNote'))}</div></aside><section class="chat-pane"><header class="chat-header">${c.kind==='dm'?av(person(c.members.find(id=>id!==actorId())),'sm online'):'<span class="channel-avatar">#</span>'}<div><h2>${esc(channelName(c))}</h2><p>${c.kind==='dm'?esc(t('demoPerson')):`${esc(memberLabel(c.members.length))} · ${esc(t(c.private?'privateGroup':'shared'))}`}</p></div><div class="header-actions"><button class="icon-btn" data-action="search-messages" aria-label="${esc(t('searchMessages'))}">${icon('search')}</button><button class="icon-btn" data-action="members" aria-label="${esc(t('viewMembers'))}">${icon('people')}</button></div></header><div class="pinned">${icon('pin')}<span><strong>${esc(t('pinned'))}:</strong> ${esc(t('pinnedText'))}</span></div>${messageSearch?`<div class="search-label">${esc(t('searching'))}: “${esc(messageSearch)}” <button data-action="clear-message-search" class="text-button" style="display:inline;font-size:9px">${esc(t('clearSearch'))}</button></div>`:''}<div class="chat-messages" id="chat-messages" role="log" aria-label="${esc(channelName(c))}">${ms.length?renderMessageItems(ms):empty(icon('chat'),t(messageSearch?'noSearch':'emptyChat'),messageSearch?'':t('emptyChatText'))}</div><div class="composer-area"><form class="composer" id="message-form"><textarea id="message-input" aria-label="${esc(t('writeMessage'))}" placeholder="${esc(t('writeMessage'))}" maxlength="4000" rows="2"></textarea><div class="composer-actions"><button type="button" class="icon-btn" data-action="emoji" aria-label="${esc(t('selectEmoji'))}">${icon('smile')}</button><button type="submit" class="send-btn" aria-label="${esc(t('send'))}">${icon('send')}</button></div><div id="emoji-root"></div></form><p class="composer-hint"><span>${esc(t('enterSend'))}</span><span>${esc(t('localOnly'))}</span></p></div></section><aside class="chat-details"><div class="details-header">${esc(t('channelDetails'))}${icon('info')}</div><div class="details-title">${esc(t('participants'))} · ${c.members.length}</div>${c.members.slice(0,5).map(id=>`<div class="detail-person">${av(person(id),'sm')}<div><b>${esc(person(id).name)}</b><small>${esc(deptName(person(id).dept))}</small></div><span class="status-dot"></span></div>`).join('')}<button class="details-link" data-action="members">${esc(t('viewMembers'))}${icon('right')}</button><div class="details-title">${esc(t('availability'))}</div>${upcoming().slice(0,2).map(r=>`<div class="detail-person">${av(person(r.person),'sm')}<div><b>${esc(person(r.person).name)}</b><small>${esc(range(r.start,r.end))} · ${esc(t('away'))}</small></div></div>`).join('')}<button class="details-link" data-action="nav" data-view="calendar">${esc(t('viewCalendar'))}${icon('arrow')}</button><div class="details-note">${icon('leaf')}<b>${esc(t('connected'))}</b><p>${esc(t('availabilityHint'))}</p></div></aside></div>`;
}
function conversationItems(filtered,c){return `${['group','dm'].map(kind=>`<div class="list-heading"><span>${esc(t(kind==='group'?'channels':'direct'))}</span>${kind==='group'?`<button data-action="new-group" aria-label="${esc(t('newChat'))}">${icon('plus')}</button>`:''}</div>${filtered.filter(a=>a.kind===kind).map(a=>`<button class="conversation-btn ${a.id===c.id?'active':''}" data-action="chat" data-id="${a.id}" ${a.id===c.id?'aria-current="true"':''}>${kind==='group'?'<span class="hash">#</span>':av(person(a.members.find(id=>id!==actorId())),'sm online')}<span class="conversation-name">${esc(channelName(a))}</span>${a.private&&kind==='group'?icon('lock','private-icon'):''}</button>`).join('')}`).join('')}${!filtered.length?`<div class="inline-empty">${esc(t('noSearch'))}</div>`:''}`}
function renderMessageItems(ms){let date='';return ms.map(m=>{const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Edmonton',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(m.at));let sep=day!==date?`<div class="day-separator">${day===TODAY?esc(t('today')):esc(fmt(day,{day:'numeric',month:'long',year:'numeric'}))}</div>`:'';date=day;const p=person(m.author);return `${sep}<article class="message ${m.author===actorId()?'mine':''}">${av(p)}<div class="message-content"><div class="message-top"><b>${esc(p.name)}</b>${m.author===actorId()?`<span class="you-tag">${esc(t('you'))}</span>`:''}<time datetime="${esc(m.at)}">${timeFmt(m.at)}</time></div><p>${esc(m.text)}</p></div></article>`}).join('')}
function empty(ico,title,sub){return `<div class="empty-state">${ico}<h3>${esc(title)}</h3><p>${esc(sub)}</p></div>`}
function renderCalendar(){
const first=new Date(month.getFullYear(),month.getMonth(),1,12);const begin=startWeek(iso(first));const approved=state.requests.filter(r=>r.status==='approved'&&(department==='all'||person(r.person).dept===department));
const days=['2026-11-02','2026-11-03','2026-11-04','2026-11-05','2026-11-06','2026-11-07','2026-11-08'];
const count=Math.ceil(((first.getDay()+6)%7+new Date(first.getFullYear(),first.getMonth()+1,0).getDate())/7)*7;
return `${pageHeading('PEOPLE & PLANNING',t('calendar'),t('calendarSub'),btn(t('request'),'request','primary','plus'))}<section class="card"><div class="calendar-toolbar"><div class="month-switch"><button class="icon-btn" data-action="month-prev" aria-label="${esc(t('monthBack'))}">${icon('left')}</button><h2>${esc(first.toLocaleDateString(locale(),{month:'long',year:'numeric'}))}</h2><button class="icon-btn" data-action="month-next" aria-label="${esc(t('monthNext'))}">${icon('right')}</button><button class="text-button" data-action="month-today" style="font-size:9px;margin-left:7px">${esc(t('today'))}</button></div><select class="filter-select" id="calendar-dept" aria-label="${esc(t('allDepartments'))}">${departmentOptions(department)}</select></div><div class="calendar-days">${days.map(d=>`<div>${esc(fmt(d,{weekday:'short'}))}</div>`).join('')}</div><div class="calendar-grid">${Array.from({length:count},(_,i)=>{const d=addDays(begin,i),dt=toDate(d);const ev=approved.filter(r=>r.start<=d&&r.end>=d);return `<div class="calendar-cell ${dt.getMonth()!==first.getMonth()?'other':''} ${dt.getDay()===0||dt.getDay()===6?'weekend':''} ${d===TODAY?'today':''}"><div class="day-number"><span>${dt.getDate()}</span></div>${ev.map(r=>`<button class="calendar-event ${person(r.person).dept==='office'?'blue':person(r.person).dept==='projects'?'purple':''}" data-action="calendar-event" data-id="${r.id}" title="${esc(person(r.person).name)} · ${esc(t('away'))}">${esc(person(r.person).name.split(' ')[0])} · ${esc(t('away'))}</button>`).join('')}</div>`}).join('')}</div><div class="calendar-footer"><div class="calendar-legend"><span class="legend-item"><i></i>${esc(t('warehouse'))}</span><span class="legend-item blue"><i></i>${esc(t('office'))}</span><span class="legend-item purple"><i></i>${esc(t('projects'))}</span></div><span>${esc(t('approvedOnly'))}</span></div></section><div class="calendar-below"><section class="card"><div class="card-header"><h2>${esc(t('upcoming'))}</h2><span style="font-size:9px;color:#9aab88">${esc(t('away'))}</span></div><div class="agenda-list">${agendaRows(upcoming().filter(r=>department==='all'||person(r.person).dept===department).slice(0,3))}</div></section><div class="privacy-card">${icon('shield')}<div><h3>${esc(t('privacyTitle'))}</h3><p>${esc(t('privacyText'))}</p></div></div></div>`;
}
function departmentOptions(selected){return ['all','warehouse','projects','office'].map(x=>`<option value="${x}" ${x===selected?'selected':''}>${esc(t(x==='all'?'allDepartments':x))}</option>`).join('')}
function renderTimeoff(){
const used=state.requests.filter(r=>r.person===actorId()&&r.type==='vacation'&&r.status==='approved'&&r.start.startsWith(TODAY.slice(0,4))).reduce((a,r)=>a+workDays(r.start,r.end),0);
const reqs=state.requests.filter(r=>requestTab==='mine'?r.person===actorId():true).slice().reverse();
return `${pageHeading('TIME FOR LIFE',t('timeoff'),t('timeoffSub'),btn(t('request'),'request','primary','plus'))}<div class="balance-cards"><div class="balance-card"><div class="label">${icon('sun')}${esc(t('vacation'))}</div><div class="balance-number">${Math.max(0,20-used)} <span>/ 20 ${esc(t('days'))}</span></div><div class="balance-bar"><span style="width:${Math.max(0,100-used*5)}%"></span></div><small>${esc(t('remaining'))} · ${used} ${esc(t('used'))}<br>${esc(t('demoAllowance'))}</small></div><div class="balance-card"><div class="label">${icon('shield')}${esc(t('sick'))} / ${esc(t('personal'))}</div><div class="balance-number" style="font-size:19px;line-height:1.5;margin-top:15px">${esc(t('companyPolicy'))}</div><small>${esc(t('notPolicy'))}</small></div><div class="balance-card" style="background:#edf2e3"><div class="label">${icon('leaf')}KEL Connect</div><div class="balance-number" style="font-size:17px;line-height:1.6;margin-top:14px">${esc(t('requestFlow'))}</div><small>${esc(t('requestFlowText'))}<br>${esc(t('workingDays'))}</small></div></div><section class="card"><div class="tabs"><button class="tab ${requestTab==='mine'?'active':''}" data-action="request-tab" data-tab="mine">${esc(t('myRequests'))}</button><button class="tab ${requestTab==='review'?'active':''}" data-action="request-tab" data-tab="review">${esc(t('approvals'))}<span class="badge">${pending().length}</span></button></div>${requestTab==='review'?`<div class="review-hint">${esc(t('reviewHint'))}</div>`:''}${reqs.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${[requestTab==='review'?'employee':'type',requestTab==='review'?'type':null,'dates','duration','status','actions'].filter(Boolean).map(k=>`<th scope="col">${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${reqs.map(r=>`<tr>${requestTab==='review'?`<td><div class="table-person">${av(person(r.person),'sm')}<div><b>${esc(person(r.person).name)}</b><small>${esc(t(person(r.person).dept))}</small></div></div></td>`:''}<td><button data-action="request-detail" data-id="${r.id}" style="padding:0;text-decoration:underline;text-underline-offset:3px">${esc(t(r.type))}</button></td><td>${esc(range(r.start,r.end))}</td><td>${workDays(r.start,r.end)} ${esc(t('days'))}</td><td><span class="tag ${r.status}">${r.status==='approved'?icon('check'):r.status==='pending'?icon('clock'):''}${esc(t(r.status))}</span></td><td>${requestTab==='review'&&r.status==='pending'&&r.person!==actorId()?`<div class="request-actions">${btn(t('approve'),'approve','small-btn','check',`data-id="${r.id}"`)}${btn(t('reject'),'reject','small-btn danger','x',`data-id="${r.id}"`)}</div>`:r.person===actorId()&&['pending','approved'].includes(r.status)?btn(t('withdraw'),'withdraw','small-btn danger','',`data-id="${r.id}"`):'<span style="color:#bac2ae">—</span>'}</td></tr>`).join('')}</tbody></table></div>`:empty(icon('sun'),t('noRequests'),t('noRequestsText'))}<div class="section-footer">${icon('info')}${esc(t('notPolicy'))}</div></section><div class="demo-callout">${icon('shield')}<p><strong>${esc(t('privacyTitle'))}.</strong> ${esc(t('privacyText'))}</p></div>`;
}
function renderPeople(){return `${pageHeading('BETTER, TOGETHER',t('people'),t('teamSub'))}<div class="people-toolbar"><div class="input-search">${icon('search')}<input type="search" id="people-search" placeholder="${esc(t('searchPeople'))}" aria-label="${esc(t('searchPeople'))}" value="${esc(peopleFilter)}"></div><select class="filter-select" id="people-dept" aria-label="${esc(t('allDepartments'))}">${departmentOptions(peopleDept)}</select></div><div id="people-grid" class="people-grid">${peopleCards()}</div><div class="demo-callout">${icon('info')}<p>${esc(t('allFictional'))} ${esc(t('demoFooter'))}</p></div>`}
function peopleCards(){const ps=state.people.filter(p=>p.active!==false&&(p.name+' '+p.job).toLowerCase().includes(peopleFilter.toLowerCase())&&(peopleDept==='all'||p.dept===peopleDept));return ps.length?ps.map(p=>`<article class="person-card">${av(p,'xl')}<h3>${esc(p.name)}</h3><p>${esc(p.job)}</p><span class="tag ${isAway(p.id)?'blue':''}"><span class="dot" style="width:4px;height:4px;background:currentColor"></span>${esc(t(isAway(p.id)?'awayStatus':'online'))}</span><span class="tag" style="margin-left:4px;background:#f3f5ee;color:#9ca58e">${esc(t(p.dept))}</span>${p.id!==actorId()?btn(t('message'),'direct-message','secondary','chat',`data-id="${p.id}"`):`<span class="self-label">${esc(t('yourProfile'))}</span>`}</article>`).join(''):`<div style="grid-column:1/-1">${empty(icon('people'),t('noPeople'),'')}</div>`}
function bindSearchInputs(){
 $('#chat-search')?.addEventListener('input',e=>{chatFilter=e.target.value;const c=state.channels.find(c=>c.id===activeChat);$('#conversations').innerHTML=conversationItems(visibleChannels().filter(c=>channelName(c).toLowerCase().includes(chatFilter.toLowerCase())),c)});
 $('#people-search')?.addEventListener('input',e=>{peopleFilter=e.target.value;$('#people-grid').innerHTML=peopleCards()});
 $('#calendar-dept')?.addEventListener('change',e=>{department=e.target.value;render()});
 $('#people-dept')?.addEventListener('change',e=>{peopleDept=e.target.value;$('#people-grid').innerHTML=peopleCards()});
 $('#message-input')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}});
}
function sendMessage(){const input=$('#message-input');if(!input)return;const text=input.value.trim();if(!text)return;if(text.length>4000){toast(t('tooLong'));return}state.messages.push({id:uid(),channel:activeChat,author:actorId(),text,at:new Date().toISOString()});persist();messageSearch='';render();$('#message-input')?.focus()}
function showModal(title,body,footer='',formId=''){
 modalReturnFocus=document.activeElement;
 $('#modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><${formId?'form':'section'} ${formId?`id="${formId}"`:''} class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" type="button" data-action="close-modal" aria-label="${esc(t('close'))}">${icon('x')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</${formId?'form':'section'}></div>`;
 document.body.style.overflow='hidden';requestAnimationFrame(()=>$('#modal-root input:not([type="checkbox"]),#modal-root select,#modal-root button')?.focus());
}
function closeModal(){ $('#modal-root').innerHTML='';document.body.style.overflow='';if(modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null }
function modalActions(submit,form=true){return `${btn(t('cancel'),'close-modal','secondary','', 'type="button"')}<button class="primary" type="${form?'submit':'button'}">${esc(submit)}</button>`}
function requestModal(){const start=nextWork(TODAY,3);showModal(t('newRequest'),`<p class="modal-subtitle">${esc(t('requestSubtitle'))}</p><label class="field"><span>${esc(t('type'))}</span><select name="type" id="leave-type">${['vacation','sick','personal'].map(x=>`<option value="${x}">${esc(t(x))}</option>`).join('')}</select></label><div class="field-row"><label class="field"><span>${esc(t('from'))}</span><input type="date" name="start" required value="${start}" min="${TODAY}" max="${addDays(TODAY,365)}"></label><label class="field"><span>${esc(t('to'))}</span><input type="date" name="end" required value="${start}" max="${addDays(TODAY,365)}"></label></div><label class="field"><span>${esc(t('note'))}</span><textarea name="note" maxlength="300" placeholder="${esc(t('notePlaceholder'))}"></textarea><small>${esc(t('noteHint'))}</small></label><div class="request-summary" id="request-summary">${icon('calendar')}<span>1 ${esc(t('days'))} · ${esc(t('workingDays'))}</span></div><p class="form-error" id="form-error" role="alert"></p>`,modalActions(t('submitRequest')),'leave-form');
 const form=$('#leave-form');const refresh=()=>{const s=form.elements.start.value,e=form.elements.end.value;$('#request-summary').innerHTML=`${icon('calendar')}<span>${workDays(s,e)} ${esc(t('days'))} · ${esc(t('workingDays'))}</span>`};
 form.elements.start.addEventListener('change',()=>{form.elements.end.min=form.elements.start.value;if(form.elements.end.value<form.elements.start.value)form.elements.end.value=form.elements.start.value;refresh()});form.elements.end.addEventListener('change',refresh);form.elements.type.addEventListener('change',()=>{form.elements.start.min=form.elements.type.value==='vacation'?TODAY:addDays(TODAY,-30)});
}
function submitRequest(form){const data=new FormData(form),start=data.get('start'),end=data.get('end'),type=data.get('type'),note=String(data.get('note')||'').trim();const err=$('#form-error');if(!['vacation','sick','personal'].includes(type)||!validDate(start)||!validDate(end)||end<start||(toDate(end)-toDate(start))/86400000>365||end>addDays(TODAY,365)){err.textContent=t('validDates');return}if(type==='vacation'&&start<TODAY){err.textContent=t('pastRequest');return}if(!workDays(start,end)){err.textContent=t('weekendOnly');return}if(state.requests.some(r=>r.person===actorId()&&['pending','approved'].includes(r.status)&&r.start<=end&&r.end>=start)){err.textContent=t('overlap');return}state.requests.push({id:uid(),person:actorId(),type,start,end,status:'pending',note:note.slice(0,300),created:TODAY});persist();closeModal();view='timeoff';requestTab='mine';render();toast(t('submitted'))}
function groupModal(){showModal(t('newConversation'),`<p class="modal-subtitle">${esc(t('groupHint'))}</p><label class="field"><span>${esc(t('groupName'))}</span><input name="name" maxlength="45" required placeholder="${esc(t('groupPlaceholder'))}"></label><div class="field"><span>${esc(t('selectMembers'))}</span><div class="check-list">${state.people.filter(p=>p.active!==false&&p.id!==actorId()).map(p=>`<label class="check-person">${av(p,'sm')}<span>${esc(p.name)}<small>${esc(t(p.dept))}</small></span><input name="member" type="checkbox" value="${p.id}" aria-label="${esc(p.name)}"></label>`).join('')}</div></div><label class="switch-field"><input type="checkbox" name="private">${icon('lock')}${esc(t('makePrivate'))}</label><p class="modal-subtitle" style="font-size:9px;margin:0">${esc(t('groupPrivateHint'))}</p><p class="form-error" id="form-error" role="alert"></p>`,modalActions(t('createGroup')),'group-form')}
function submitGroup(form){const data=new FormData(form),name=String(data.get('name')||'').trim(),members=data.getAll('member').filter(id=>state.people.some(p=>p.id===id));if(!name||!members.length){$('#form-error').textContent=t('requiredGroup');return}const c={id:uid(),kind:'group',name:name.slice(0,45),members:[actorId(),...new Set(members)],private:data.get('private')==='on'};state.channels.push(c);persist();activeChat=c.id;view='messages';chatFilter='';messageSearch='';closeModal();render();toast(t('groupCreated'))}
function showMembers(){const c=state.channels.find(c=>c.id===activeChat);showModal(channelName(c),`<p class="modal-subtitle">${esc(t(c.kind==='dm'||c.private?'privateGroup':'shared'))} · ${esc(memberLabel(c.members.length))}<br>${esc(t('allFictional'))}</p>${c.members.map(id=>`<div class="detail-person">${av(person(id))}<div><b>${esc(person(id).name)}</b><small>${esc(person(id).job)}</small></div></div>`).join('')}`,btn(t('close'),'close-modal','primary','', 'type="button"'))}
function requestDetails(id,publicOnly=false){const r=state.requests.find(r=>r.id===id);if(!r)return;const p=person(r.person);showModal(t(publicOnly?'privateCalendar':'requestDetails'),`<div class="selected-info">${av(p,'lg')}<div><h3>${esc(p.name)}</h3><p>${esc(p.job)}</p></div></div><div class="info-section"><b>${esc(t('dates'))}</b>${esc(range(r.start,r.end))} · ${workDays(r.start,r.end)} ${esc(t('days'))}</div>${publicOnly?`<div class="privacy-card" style="padding:15px">${icon('shield')}<div><h3>${esc(t('privacyTitle'))}</h3><p>${esc(t('privateCalendarText'))}</p></div></div>`:`<div class="info-section"><b>${esc(t('type'))}</b>${esc(t(r.type))}</div><div class="info-section"><b>${esc(t('status'))}</b><span class="tag ${r.status}">${esc(t(r.status))}</span></div><div class="info-section"><b>${esc(t('requestNote'))}</b>${esc(r.note||t('noNote'))}</div>`}`,btn(t('close'),'close-modal','primary','', 'type="button"'))}
function showAbout(){showModal(t('aboutTitle'),`<p class="modal-subtitle">${esc(t('aboutLead'))}</p>${[['aboutOne','aboutOneText'],['aboutTwo','aboutTwoText'],['aboutThree','aboutThreeText']].map(([h,p])=>`<div class="info-section"><b>${esc(t(h))}</b>${esc(t(p))}</div>`).join('')}`,btn(t('close'),'close-modal','primary','', 'type="button"'))}
function changeRequest(id,status){const r=state.requests.find(r=>r.id===id);if(!r)return;if(['approved','rejected'].includes(status)&&r.person===actorId()){toast(t('selfReview'));return}if(status!=='cancelled'&&r.status!=='pending')return;if(status==='cancelled'&&r.person!==actorId())return;r.status=status;persist();render();toast(t('updated'))}
document.addEventListener('click',e=>{
 if(e.target.dataset.backdrop){closeModal();return}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='nav'){view=b.dataset.view;render();window.scrollTo(0,0)}
 else if(a==='language'){const draft=$('#message-input')?.value;lang=lang==='uk'?'en':'uk';persist();render();if(draft&&$('#message-input'))$('#message-input').value=draft}
 else if(a==='menu')$('#sidebar').classList.add('open');
 else if(a==='close-menu')$('#sidebar').classList.remove('open');
 else if(a==='chat'){activeChat=id;view='messages';messageSearch='';emojiOpen=false;render()}
 else if(a==='new-group')groupModal();
 else if(a==='request')requestModal();
 else if(a==='close-modal')closeModal();
 else if(a==='members')showMembers();
 else if(a==='about')showAbout();
 else if(a==='calendar-event')requestDetails(id,true);
 else if(a==='request-detail')requestDetails(id);
 else if(a==='request-tab'){requestTab=b.dataset.tab;render()}
 else if(a==='month-prev'||a==='month-next'){month=new Date(month.getFullYear(),month.getMonth()+(a==='month-prev'?-1:1),1,12);render()}
 else if(a==='month-today'){month=toDate(TODAY);render()}
 else if(a==='direct-message'){let c=state.channels.find(c=>c.kind==='dm'&&c.members.includes(id)&&c.members.includes(actorId()));if(!c){c={id:uid(),kind:'dm',members:[actorId(),id],private:true};state.channels.push(c);persist()}activeChat=c.id;view='messages';messageSearch='';chatFilter='';render();$('#message-input')?.focus()}
 else if(a==='approve')changeRequest(id,'approved');
 else if(a==='reject')changeRequest(id,'rejected');
 else if(a==='withdraw')changeRequest(id,'cancelled');
 else if(a==='search-messages')showModal(t('searchMessages'),`<label class="field"><span>${esc(t('searchText'))}</span><input name="query" required maxlength="100" value="${esc(messageSearch)}" placeholder="${esc(t('searchText'))}"></label>`,modalActions(t('find')),'search-form');
 else if(a==='clear-message-search'){messageSearch='';render()}
 else if(a==='emoji'){emojiOpen=!$('#emoji-root').innerHTML;$('#emoji-root').innerHTML=emojiOpen?`<div class="emoji-panel">${['👍','👋','😊','☕','📦','✅'].map(x=>`<button type="button" data-action="insert-emoji" data-emoji="${x}" aria-label="${x}">${x}</button>`).join('')}</div>`:''}
 else if(a==='insert-emoji'){const input=$('#message-input');input.value+=b.dataset.emoji;$('#emoji-root').innerHTML='';input.focus()}
 else if(a==='reset')showModal(t('resetTitle'),`<p class="modal-subtitle">${esc(t('resetText'))}</p>`,`${btn(t('cancel'),'close-modal','secondary','', 'type="button"')}${btn(t('resetButton'),'confirm-reset','primary','refresh', 'type="button"')}`);
 else if(a==='confirm-reset'){state=seed();initializeHR();state.language=lang;activeChat='general';chatFilter='';messageSearch='';requestTab='mine';persist();closeModal();render();toast(t('resetDone'))}
});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id==='message-form')sendMessage();else if(form.id==='leave-form')submitRequest(form);else if(form.id==='group-form')submitGroup(form);else if(form.id==='search-form'){messageSearch=String(new FormData(form).get('query')||'').trim();closeModal();render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar')?.classList.remove('open');closeModal();if($('#emoji-root'))$('#emoji-root').innerHTML=''}if(e.key==='Tab'&&$('#modal-root .modal')){const focus=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]',$('#modal-root .modal'));const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('storage',e=>{if(e.key!==STORE||!e.newValue)return;try{const data=JSON.parse(e.newValue);if(data.version===1){const draft=$('#message-input')?.value;state=data;initializeHR();lang=state.language==='en'?'en':'uk';render();if(draft&&$('#message-input'))$('#message-input').value=draft}}catch{}});
